import React, { useState, useEffect, useRef } from "react";
import { Link, NavLink, useLocation, useSearchParams } from "react-router-dom";

// Импорт логотипов (пути должны быть верными)
import plLogo from "../../assets/leagues/premier-league.png";
import blLogo from "../../assets/leagues/bundesliga.png";
import saLogo from "../../assets/leagues/serie-a.png";
import pdLogo from "../../assets/leagues/la-liga.png";
import flLogo from "../../assets/leagues/ligue-1.png";

const leagues = [
  { code: null, name: "Все матчи", logo: null },
  { code: "Premier_League", name: "Premier League", logo: plLogo },
  { code: "La_Liga", name: "La Liga", logo: pdLogo },
  { code: "Serie_A", name: "Serie A", logo: saLogo },
  { code: "Bundesliga", name: "Bundesliga", logo: blLogo },
  { code: "Ligue_1", name: "Ligue 1", logo: flLogo },
];

function Header() {
  const [isDropdown, setIsDropdown] = useState(false);
  const dropdownRef = useRef(null);
  const location = useLocation();
  const [searchParams] = useSearchParams();
  const currentLeagueCode = searchParams.get("league");

  // Закрытие при клике вне области
  useEffect(() => {
    function handleClickOutside(event) {
      if (dropdownRef.current && !dropdownRef.current.contains(event.target)) {
        setIsDropdown(false);
      }
    }
    document.addEventListener("mousedown", handleClickOutside);
    return () => document.removeEventListener("mousedown", handleClickOutside);
  }, []);

  // Закрытие при переходе
  useEffect(() => {
    setIsDropdown(false);
  }, [location.pathname, location.search]);

  return (
    <header className="bg-gray-950 border-b border-gray-800 sticky top-0 z-50 w-full">
      <div className="container mx-auto px-4 h-20 flex items-center justify-between gap-4">
        {/* 1. ЛОГОТИП */}
        <Link to="/" className="flex-shrink-0">
          <span className="text-2xl font-black italic tracking-tighter text-white">
            NEURO<span className="text-red-600">PREDICT</span>
          </span>
        </Link>

        {/* 2. ПОИСК (PLACEHOLDER) */}
        <div className="hidden md:flex flex-grow max-w-md relative">
          <input
            type="text"
            placeholder="Поиск матча или команды..."
            className="w-full bg-gray-900 border border-gray-800 rounded-xl py-2 px-4 text-xs text-gray-300 focus:outline-none focus:border-red-600 transition-all"
            disabled // Пока функционал не реализован
          />
          <span className="absolute right-3 top-2.5 text-gray-600 text-xs">
            ⌘K
          </span>
        </div>

        {/* 3. НАВИГАЦИЯ */}
        <nav className="flex items-center gap-2 md:gap-4">
          {/* Сравнение команд (PLACEHOLDER) */}
          <div className="hidden sm:block opacity-50 cursor-not-allowed">
            <span className="text-[10px] font-black uppercase text-gray-400 tracking-widest px-3 py-2 border border-gray-800 rounded-lg">
              Сравнение H2H
            </span>
          </div>

          {/* ВЫБОР ЛИГИ (ВИЗУАЛЬНЫЙ DROP DOWN) */}
          <div className="relative" ref={dropdownRef}>
            <button
              onClick={() => setIsDropdown(!isDropdown)}
              className={`flex items-center gap-2 px-4 py-2 rounded-xl border transition-all duration-300 ${
                isDropdown || currentLeagueCode
                  ? "bg-red-600 border-red-600 text-white shadow-[0_0_15px_rgba(220,38,38,0.4)]"
                  : "bg-gray-900 border-gray-800 text-gray-400 hover:border-gray-600"
              }`}
            >
              <span className="text-xs font-black uppercase tracking-widest">
                {currentLeagueCode
                  ? currentLeagueCode.replace("_", " ")
                  : "Выбрать Лигу"}
              </span>
              <svg
                className={`w-3 h-3 transform transition-transform ${isDropdown ? "rotate-180" : ""}`}
                fill="none"
                stroke="currentColor"
                viewBox="0 0 24 24"
              >
                <path
                  strokeLinecap="round"
                  strokeLinejoin="round"
                  strokeWidth="3"
                  d="M19 9l-7 7-7-7"
                />
              </svg>
            </button>

            {/* ВЫПАДАЮЩАЯ СЕТКА С ЛОГОТИПАМИ */}
            {isDropdown && (
              <div className="absolute right-0 mt-3 w-[320px] md:w-[450px] bg-gray-950 border border-gray-800 rounded-2xl shadow-2xl p-4 grid grid-cols-3 gap-3 animate-in fade-in zoom-in duration-200">
                {leagues.map((league) => (
                  <NavLink
                    key={league.code}
                    to={league.code ? `/?league=${league.code}` : "/"}
                    className={({ isActive }) => `
                      flex flex-col items-center justify-center p-3 rounded-xl border transition-all
                      ${
                        isActive &&
                        ((!currentLeagueCode && !league.code) ||
                          currentLeagueCode === league.code)
                          ? "bg-red-600/10 border-red-600 text-white"
                          : "bg-gray-900 border-transparent text-gray-500 hover:border-gray-700 hover:text-gray-300"
                      }
                    `}
                  >
                    <div className="h-10 w-10 mb-2 flex items-center justify-center">
                      {league.logo ? (
                        <img
                          src={league.logo}
                          alt=""
                          className="h-full w-full object-contain"
                        />
                      ) : (
                        <span className="text-xs font-black uppercase">
                          ALL
                        </span>
                      )}
                    </div>
                    <span className="text-[10px] font-bold text-center leading-tight uppercase tracking-tighter">
                      {league.name}
                    </span>
                  </NavLink>
                ))}
              </div>
            )}
          </div>
        </nav>
      </div>
    </header>
  );
}

export default Header;
